"""Warehouse side: catalog entries, goods received, stock counts."""
from hbstock.models import Product
from hbstock.util.sku import is_sku, normalize_sku, parse_qty


class InventoryService:
    def __init__(self, repo, settings):
        self.repo = repo
        self.settings = settings

    def create(self, payload):
        sku = normalize_sku(payload.get("sku"))
        if not is_sku(sku):
            raise ValueError("sku must look like GD-104")
        name = str(payload.get("name", "")).strip()
        if not name:
            raise ValueError("name is required")
        category = str(payload.get("category", "goods")).strip().lower()
        if category not in self.settings.categories:
            raise ValueError(f"unknown category {category}")
        price = parse_qty(payload.get("price"))
        on_hand = parse_qty(payload.get("on_hand", 0), allow_zero=True)
        product = Product(sku=sku, name=name, category=category, price=price, on_hand=on_hand)
        self.repo.add_product(product)
        self.repo.log(sku, "create", on_hand)
        return product

    def receive(self, sku, qty):
        product = self.repo.product(normalize_sku(sku))
        qty = parse_qty(qty)
        product.on_hand += qty
        self.repo.log(product.sku, "receive", qty)
        return product

    def count(self, sku, counted):
        """Stock count: the shelf wins over the books."""
        product = self.repo.product(normalize_sku(sku))
        counted = parse_qty(counted, allow_zero=True)
        delta = counted - product.on_hand
        product.on_hand = counted
        self.repo.log(product.sku, "count", delta)
        return product
"""Market-side view, read back from the vendor so it matches what shoppers see."""
from hbstock.market.feed import market_qty


class ListingService:
    def __init__(self, repo, client, settings, cache):
        self.repo = repo
        self.client = client
        self.settings = settings
        self.cache = cache

    def invalidate(self):
        self.cache.invalidate("market")

    def _rows(self):
        cached = self.cache.get("market:rows")
        if cached is None:
            cached = {row.sku: row for row in self.client.rows()}
            self.cache.put("market:rows", cached)
        return cached

    def listing(self):
        rows = self._rows()
        items = []
        for product in self.repo.products():
            row = rows.get(product.sku)
            items.append({
                "sku": product.sku,
                "name": product.name,
                "listed": row is not None,
                "market_qty": row.qty if row else 0,
                "on_sale": bool(row and row.qty > 0),
            })
        return {"items": items, "on_sale": sum(1 for i in items if i["on_sale"])}

    def product_view(self, sku):
        product = self.repo.product(sku)
        row = self._rows().get(product.sku)
        view = product.to_dict()
        view["market"] = {
            "listed": row is not None,
            "qty": row.qty if row else 0,
            "on_sale": bool(row and row.qty > 0),
        }
        return view

    def drift(self):
        """Products whose market quantity differs from what we mean to offer."""
        rows = self._rows()
        out = []
        for product in self.repo.products():
            want = market_qty(product, self.settings)
            row = rows.get(product.sku)
            have = row.qty if row else None
            if have != want and not (have is None and want == 0):
                out.append({"sku": product.sku, "ours": want, "market": have})
        return {"items": out, "count": len(out)}
"""Domain objects and service-level errors."""
from dataclasses import dataclass, field


class NotFound(Exception):
    pass


class Conflict(Exception):
    pass


class VendorError(Exception):
    """The stock sync CLI rejected a call (opaque vendor code in .code)."""

    def __init__(self, code, command):
        super().__init__(f"stockpush {command} failed: {code}")
        self.code = code
        self.command = command


@dataclass
class Product:
    sku: str
    name: str
    category: str
    price: int
    on_hand: int = 0
    reserved: int = 0

    @property
    def available(self):
        return self.on_hand - self.reserved

    def to_dict(self):
        return {
            "sku": self.sku,
            "name": self.name,
            "category": self.category,
            "price": self.price,
            "on_hand": self.on_hand,
            "reserved": self.reserved,
            "available": self.available,
        }


OPEN = "open"
SHIPPED = "shipped"
CANCELLED = "cancelled"


@dataclass
class Order:
    order_id: str
    sku: str
    qty: int
    status: str = OPEN
    history: list = field(default_factory=list)

    def to_dict(self):
        return {"id": self.order_id, "sku": self.sku, "qty": self.qty, "status": self.status}


@dataclass(frozen=True)
class MarketRow:
    sku: str
    qty: int
    st: int
    transfer: str


@dataclass(frozen=True)
class Transfer:
    transfer_id: str
    lines: int

